package com.bleachmod.registry;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * NPCs without quests, one per skin in tools/appearance/skins (generated by split_skin.py).
 * Read from the jar while registries are built, so client and server register the same entities.
 */
public final class NpcRoster {
    public static final String PATH = "/data/bleachmod/npcs/roster.json";

    public record Entry(String id, int eggPrimary, int eggSecondary) { }

    private static List<Entry> entries;

    private NpcRoster() { }

    public static synchronized List<Entry> entries() {
        if (entries == null) {
            try (InputStream in = NpcRoster.class.getResourceAsStream(PATH)) {
                if (in == null) throw new IllegalStateException("Missing " + PATH);
                entries = parse(JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject());
            } catch (java.io.IOException e) {
                throw new IllegalStateException("Unreadable " + PATH, e);
            }
        }
        return entries;
    }

    public static List<Entry> parse(JsonObject json) {
        List<Entry> out = new ArrayList<>();
        for (JsonElement element : json.getAsJsonArray("npcs")) {
            JsonObject o = element.getAsJsonObject();
            String id = o.get("id").getAsString();
            if (!id.matches("[a-z0-9_]{1,40}")) throw new IllegalArgumentException("Bad NPC id " + id);
            out.add(new Entry(id, color(o.get("eggPrimary").getAsString()), color(o.get("eggSecondary").getAsString())));
        }
        return List.copyOf(out);
    }

    private static int color(String hex) {
        if (!hex.matches("#[0-9A-Fa-f]{6}")) throw new IllegalArgumentException("Bad egg color " + hex);
        return Integer.parseInt(hex.substring(1), 16);
    }
}
